CREATE TABLE sourcing_research(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,need_id uuid NOT NULL REFERENCES procurement_needs,need_version integer NOT NULL,status text NOT NULL CHECK(status IN ('researching','completed','failed','needs_configuration')),error text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(run_id,need_id,need_version),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE sourcing_queries(id uuid PRIMARY KEY,research_id uuid NOT NULL REFERENCES sourcing_research,project_id uuid NOT NULL,run_id uuid NOT NULL,query text NOT NULL,request_id text,duration_ms integer NOT NULL,created_at timestamptz NOT NULL,FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE source_snapshots(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,query_id uuid NOT NULL REFERENCES sourcing_queries,url text NOT NULL,title text,content text NOT NULL,retrieved_at timestamptz NOT NULL,provenance text NOT NULL CHECK(provenance IN ('live','cache','fixture')),content_hash text NOT NULL,FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE supplier_candidates(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,research_id uuid NOT NULL REFERENCES sourcing_research,need_id uuid NOT NULL REFERENCES procurement_needs,need_version integer NOT NULL,version integer NOT NULL DEFAULT 1,source_snapshot_id uuid NOT NULL REFERENCES source_snapshots,candidate jsonb NOT NULL,calculation jsonb,delivery_date date,delivery_status text NOT NULL,known_transport numeric,known_tax numeric,FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE sourcing_selections(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,need_id uuid NOT NULL REFERENCES procurement_needs,need_version integer NOT NULL,candidate_id uuid REFERENCES supplier_candidates,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE purchases(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES members,source_message_id text NOT NULL,issuer text,reference text,invoice_date date,issuer_key text,reference_key text,document_hash text NOT NULL,currency text NOT NULL,total numeric,status text NOT NULL,version integer NOT NULL,evidence_ids uuid[] NOT NULL,content_hash text NOT NULL,UNIQUE(run_id,document_hash),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE UNIQUE INDEX purchase_invoice_identity ON purchases(run_id,issuer_key,reference_key) WHERE issuer_key IS NOT NULL AND reference_key IS NOT NULL;
CREATE TABLE purchase_lines(id uuid PRIMARY KEY,purchase_id uuid NOT NULL REFERENCES purchases,material_id uuid NOT NULL REFERENCES materials,quantity numeric NOT NULL,received_quantity numeric NOT NULL DEFAULT 0,unit text NOT NULL,unit_price numeric,total numeric);
CREATE TABLE purchase_receipts(id uuid PRIMARY KEY,purchase_id uuid NOT NULL REFERENCES purchases,project_id uuid NOT NULL,run_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES members,source_message_id text NOT NULL,lines jsonb NOT NULL,confirmed_at timestamptz NOT NULL,UNIQUE(run_id,purchase_id,source_message_id),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE purchase_operations(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES members,idempotency_key text NOT NULL,proposal jsonb NOT NULL,result jsonb NOT NULL,UNIQUE(run_id,idempotency_key),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE report_snapshots(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,report_date date NOT NULL,project_version integer NOT NULL,audience text NOT NULL,content_hash text NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,run_id,report_date,project_version,audience),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
